package dev.vibe.ui.screen;
import dev.vibe.camera.CameraRig;
import dev.vibe.module.impl.movement.FreecamModule;
import java.io.IOException;
import java.util.*;
import net.minecraft.client.gui.*;
import org.lwjgl.input.Keyboard;
import org.lwjgl.input.Mouse;
/** Compact Skeet-style route editor. All edits affect render-camera poses only. */
public final class CameraRigGui extends GuiScreen {
    private final FreecamModule module;private final GuiScreen parent;private final List<GuiTextField> fields=new ArrayList<>();private float uiScale=1;private int left,top,selected=-1,scroll;private String status="Capture camera poses, edit durations, then preview or play.";
    public CameraRigGui(FreecamModule module,GuiScreen parent){this.module=module;this.parent=parent;}
    @Override public void initGui(){uiScale=Math.min(1,Math.min(width/480F,height/345F));left=Math.max(4,(Math.round(width/uiScale)-464)/2);top=Math.max(4,(Math.round(height/uiScale)-330)/2);fields.clear();String[] names={"X","Y","Z","Yaw","Pitch","Roll","Seconds"};for(int i=0;i<names.length;i++){GuiTextField f=new GuiTextField(i,fontRendererObj,left+311,top+49+i*26,136,18);f.setMaxStringLength(20);fields.add(f);}buttonList.clear();button(1,12,39,94,"Capture");button(2,111,39,94,"Delete");button(3,12,248,94,"Move up");button(4,111,248,94,"Move down");button(5,235,244,99,"Apply pose");button(6,341,244,110,"Preview path");button(7,12,278,94,"Play");button(8,111,278,94,"Stop");button(9,235,278,99,"Timing mode");button(10,341,278,110,"Done");if(selected>=module.rig.poses().size())selected=module.rig.poses().size()-1;fill();Keyboard.enableRepeatEvents(true);}
    private void button(int id,int x,int y,int w,String text){buttonList.add(new DarkButton(id,left+x,top+y,w,text));}
    private void fill(){if(selected<0||selected>=module.rig.poses().size())return;CameraRig.Pose p=module.rig.poses().get(selected);double[] values={p.x,p.y,p.z,p.yaw,p.pitch,p.roll,p.seconds};for(int i=0;i<values.length;i++)fields.get(i).setText(String.format(Locale.ROOT,"%.3f",values[i]));}
    @Override public void drawScreen(int mx,int my,float partial){drawDefaultBackground();mx=Math.round(mx/uiScale);my=Math.round(my/uiScale);net.minecraft.client.renderer.GlStateManager.pushMatrix();net.minecraft.client.renderer.GlStateManager.scale(uiScale,uiScale,1);try{Gui.drawRect(left,top,left+464,top+325,0xF0101113);Gui.drawRect(left+1,top+1,left+463,top+3,0xFF89B75B);drawString(fontRendererObj,"Camera Rig",left+13,top+14,0xFFF0F0F0);drawString(fontRendererObj,module.rigMode.getValue(),left+330,top+14,0xFF89B75B);Gui.drawRect(left+11,top+67,left+206,top+238,0xFF191A1E);
        List<CameraRig.Pose> poses=module.rig.poses();for(int i=scroll;i<Math.min(poses.size(),scroll+7);i++){int y=top+70+(i-scroll)*23;if(selected==i)Gui.drawRect(left+13,y,left+204,y+21,0xFF30372B);CameraRig.Pose p=poses.get(i);drawString(fontRendererObj,"Pose "+(i+1),left+19,y+4,0xFFE9ECE6);drawString(fontRendererObj,String.format(Locale.ROOT,"%.1fs",p.seconds),left+155,y+4,0xFFA9B4A2);}
        String[] labels={"X","Y","Z","Yaw","Pitch","Roll","Seconds"};for(int i=0;i<fields.size();i++){drawString(fontRendererObj,labels[i],left+240,top+54+i*26,0xFFB8BBB5);fields.get(i).drawTextBox();}
        int x=left+14,y=top+305,w=435;Gui.drawRect(x,y,x+w,y+4,0xFF343A30);double total=module.rig.duration(module.rigMode.is("Fixed Speed"),module.rigSpeed.getDouble());if(total>0){int marker=(int)(w*Math.min(1,module.rig.elapsed()/total));Gui.drawRect(x+marker-1,y-2,x+marker+1,y+6,0xFFAFDA7C);}
        drawString(fontRendererObj,fontRendererObj.trimStringToWidth(status,435),left+14,top+316,0xFF9EAA95);super.drawScreen(mx,my,partial);}finally{net.minecraft.client.renderer.GlStateManager.popMatrix();}}
    @Override protected void actionPerformed(GuiButton b){try{switch(b.id){case 1:if(mc.theWorld==null||mc.thePlayer==null){status="Join a world to capture a camera pose.";break;}if(!module.isEnabled())module.setEnabled(true);module.rig.capture(module.getFlight());selected=module.rig.poses().size()-1;scroll=Math.max(0,selected-6);fill();status="Pose captured.";break;
        case 2:module.rig.remove(selected);selected=Math.min(selected,module.rig.poses().size()-1);fill();break;case 3:module.rig.move(selected,-1);selected=Math.max(0,selected-1);fill();break;case 4:module.rig.move(selected,1);selected=Math.min(module.rig.poses().size()-1,selected+1);fill();break;
        case 5:if(selected<0)break;double[] v=new double[7];for(int i=0;i<7;i++)v[i]=Double.parseDouble(fields.get(i).getText());CameraRig.Pose p=new CameraRig.Pose(v[0],v[1],v[2],v[3],v[4],v[5],"");p.seconds=v[6];module.rig.update(selected,p);status="Pose updated.";break;
        case 6:module.rigPreview.toggle();status=module.rigPreview.isEnabled()?"Green segments are clear; red segments are obstructed.":"Path preview hidden.";break;
        case 7:if(mc.theWorld!=null&&mc.thePlayer!=null){if(!module.isEnabled())module.setEnabled(true);if(module.rig.play()){module.rig.seek(0,module.getFlight(),false,1,false);status="Playing. Scrub the timeline to inspect a point.";}}break;case 8:module.rig.stop();status="Stopped.";break;
        case 9:module.rigMode.setValue(module.rigMode.is("Fixed Speed")?"Per Pose":"Fixed Speed");status=module.rigMode.getValue();break;case 10:mc.displayGuiScreen(parent);break;default:break;}}catch(IllegalArgumentException invalid){status=invalid.getMessage()==null?"Enter valid numeric pose values.":invalid.getMessage();}}
    @Override protected void mouseClicked(int mx,int my,int button)throws IOException{mx=Math.round(mx/uiScale);my=Math.round(my/uiScale);for(GuiTextField f:fields)f.mouseClicked(mx,my,button);if(button==0&&mx>=left+12&&mx<left+206&&my>=top+70&&my<top+231){int i=scroll+(my-top-70)/23;if(i<module.rig.poses().size()){selected=i;fill();}}if(button==0&&mx>=left+14&&mx<=left+449&&my>=top+301&&my<=top+313){module.rig.stop();double duration=module.rig.duration(module.rigMode.is("Fixed Speed"),module.rigSpeed.getDouble());module.rig.seek((mx-left-14)/435.0*duration,module.getFlight(),module.rigMode.is("Fixed Speed"),module.rigSpeed.getDouble(),module.rigCollision.isEnabled());}super.mouseClicked(mx,my,button);}
    @Override public void handleMouseInput()throws IOException{super.handleMouseInput();int wheel=Mouse.getEventDWheel();if(wheel!=0)scroll=Math.max(0,Math.min(Math.max(0,module.rig.poses().size()-7),scroll-(wheel>0?1:-1)));}
    @Override protected void keyTyped(char c,int key)throws IOException{if(key==Keyboard.KEY_ESCAPE){mc.displayGuiScreen(parent);return;}if(key==Keyboard.KEY_TAB){for(int i=0;i<fields.size();i++)if(fields.get(i).isFocused()){fields.get(i).setFocused(false);fields.get((i+1)%fields.size()).setFocused(true);return;}fields.get(0).setFocused(true);return;}for(GuiTextField f:fields)if(f.isFocused()){f.textboxKeyTyped(c,key);return;}}
    @Override public boolean doesGuiPauseGame(){return false;}@Override public void onGuiClosed(){Keyboard.enableRepeatEvents(false);dev.vibe.Vibe v=dev.vibe.Vibe.getInstance();if(v!=null&&v.getConfig()!=null&&!v.getConfig().isLoading())v.getConfig().save(v.getModuleManager());}
    private static final class DarkButton extends GuiButton {DarkButton(int id,int x,int y,int w,String text){super(id,x,y,w,20,text);}@Override public void drawButton(net.minecraft.client.Minecraft mc,int mx,int my){if(!visible)return;hovered=mx>=xPosition&&my>=yPosition&&mx<xPosition+width&&my<yPosition+height;Gui.drawRect(xPosition,yPosition,xPosition+width,yPosition+height,hovered?0xFF3A4432:0xFF282D25);Gui.drawRect(xPosition,yPosition,xPosition+width,yPosition+1,0xFF617649);drawCenteredString(mc.fontRendererObj,displayString,xPosition+width/2,yPosition+6,0xFFDFE7D8);}}
}
